"""Renders data/timing-summary.md from data/timing.json and data/grid-verification.json (stdlib only)."""
import json, sys
sys.stdout.reconfigure(encoding="utf-8")
R = "C:\\Users\\burcu\\Documents\\klip-her-sabah\\data\\"
T = json.load(open(R + "timing.json", encoding="utf-8")); V = json.load(open(R + "grid-verification.json", encoding="utf-8"))
ts = lambda t: "-" if t is None else "%d:%05.2f" % (int(t // 60), t % 60)
tp = T["tempo"]; S = T["sections"]; Ls = T["lines"]
o = []
o.append("# Her Sabah Bastan - timing summary\n")
o.append("Generated by tools/timing/*.py from `sarki/her-sabah-bastan.wav` (%.2f s, 30 fps = %d frames). Every number below comes from a run; see the end for what was not measured.\n" % (T["duration"], round(T["duration"] * 30)))
o.append("## Tempo and grid\n")
eq = V["equation"]
o.append("- Tempo is **not constant**: it accelerates from %.2f BPM (first 20 s) to %.2f BPM (last 20 s); mean %.3f BPM, mean beat period %.5f s. Knots every 20 s (BPM): %s." % (tp["bpm_first_20s"], tp["bpm_last_20s"], tp["bpm_mean"], tp["beat_period_mean"], ", ".join("%.1f" % b for b in tp["knots_bpm"][:13])))
o.append("- Beat grid = smooth tempo curve fitted to the onset envelope (`beats[]`, %d beats). A single constant-BPM grid would be off by %s ms at t = 30/60/120/180/240 s, so use `beats[]`/`downbeats[]`, never `bpm`, for sync." % (tp["beats_total"], "/".join(str(int(tp["straight_grid_drift_ms"][k])) for k in ("30", "60", "120", "180", "240"))))
o.append("- Structure equation: **%d bars x 4 beats x %.5f s = %.3f s**; first downbeat %.3f s to last beat %.3f s = %.3f s (file %.3f s). All 129 bars are 4 beats (bar 129 lists 5 because the grid runs on to the file end)." % (eq["bars"], eq["mean_beat_period"], eq["bars_x4_x_period"], eq["first_downbeat"], T["beats"][-1], eq["span_first_downbeat_to_last_beat_s"], eq["audio_end"]))
_last = max(V["energy_steps"], key=lambda e: e["t"])
o.append("- Independent integer check: the last abrupt energy event (%+.1f dB at %.2f s, detected from RMS only) lies %.2f bars after the first downbeat ((%.2f - %.3f) / (4 x %.5f)) and %+d ms from a downbeat." % (_last["step_db"], _last["t"], (_last["t"] - T["downbeats"][0]) / (4 * eq["mean_beat_period"]), _last["t"], T["downbeats"][0], eq["mean_beat_period"], int(_last["dt_to_downbeat_ms"])))
o.append("- Grid accuracy: onset-snapped beats vs fitted grid, median |dev| %.1f ms, max %.1f ms, %d of %d beats beyond 1 frame (33.3 ms; weak-onset beats). Kick-band onsets vs nearest beat per 30 s window: window medians between %+.1f and %+.1f ms (spread %.1f ms < 1 frame), so no drift above 1 frame at 30 fps anywhere." % (
    tp["onset_residual_ms"]["median_abs"], tp["onset_residual_ms"]["max"], tp["onset_residual_ms"]["n_over_one_frame"], tp["onset_residual_ms"]["n"],
    min(r["median_ms"] for r in V["kick_vs_beat_per_30s"]), max(r["median_ms"] for r in V["kick_vs_beat_per_30s"]),
    max(r["median_ms"] for r in V["kick_vs_beat_per_30s"]) - min(r["median_ms"] for r in V["kick_vs_beat_per_30s"])))
w = V["phase0_wins"]
o.append("- Downbeat phase: chosen by a dynamic programme over kick-band onset, bass/full chroma change and energy step. Check against the final grid: bass-chord changes are strongest on the chosen bar start in %d of %d sections, kick-band onsets in %d of %d (kick sits on beats 1 and 3, so it fixes parity, chord change fixes 1 vs 3). Ties/anticipated chords in the other sections. Final bar (bar 129, %.3f s) coincides with a +17 dB energy step at -1 ms." % (w["chord_change"], w["sections"], w["kick"], w["sections"], T["downbeats"][-1]))
o.append("- Intro (first ~8 s) has almost no rhythmic content, so the grid there is least certain (kick window 0-30 s median %+.1f ms)." % V["kick_vs_beat_per_30s"][0]["median_ms"])
o.append("")
o.append("## Sections (bar-snapped; start rule in the last column)\n")
o.append("| # | section | start | end | bars (n) | mean dB | tag | singers heard (hint) | key | start rule |")
o.append("|---|---|---|---|---|---|---|---|---|---|")
for i, s in enumerate(S):
    sh = ", ".join("%s %d" % (k, v) for k, v in s["singers_heard"].items()) or "-"
    o.append("| %d | %s | %s | %s | %d-%d (%d) | %.1f | %s | %s | %s (r %.2f) | %s |" % (i + 1, s["name"], ts(s["start"]), ts(s["end"]), s["start_bar"], s["end_bar"], s["n_bars"], s["mean_db"], s["singer_tag"] or "-", sh, s["key"]["best"], s["key"]["r"], s["start_rule"]))
o.append("\nVocal-led section starts (no big energy step) are the downbeat at/before the first sung word + 0.5 s; vocals enter ~2 beats after the bar line in most sections, so a start can be +-1 bar off from where a musician would count it. Lyrics order in `sozler.md` held; extra unlisted material is flagged below.\n")
o.append("## Lines (anchored = at least half the words matched to measured whisper words; start/end only from matched words)\n")
o.append("| section | tag | hint (conf) | f0 Hz | start | end | match | anchored | text / what whisper heard |")
o.append("|---|---|---|---|---|---|---|---|---|")
for L in Ls:
    txt = L["text"].replace("|", "/")
    if L["matched_words"] < L["n_words"] and L["heard"]: txt += " -> heard: " + L["heard"]
    elif L["matched_words"] == 0: txt += " -> nothing matched"
    if L.get("energy_hint"): txt += " (energy-only vocal activity %s-%s)" % (ts(L["energy_hint"]["start"]), ts(L["energy_hint"]["end"]))
    o.append("| %s | %s | %s (%s) | %s | %s | %s | %d/%d | %s | %s |" % (L["section"], L["singer_tag"] or "-", L["singer_hint"], L["singer_hint_confidence"] or "-", L["f0_median_hz"] if L["f0_median_hz"] else "-", ts(L["start"]), ts(L["end"]), L["matched_words"], L["n_words"], "yes" if L["anchored"] else "NO", txt))
na = sum(L["anchored"] for L in Ls)
o.append("\nAnchored lines: **%d/%d**. Fully matched (all words): %d/%d." % (na, len(Ls), sum(L["matched_words"] == L["n_words"] for L in Ls), len(Ls)))
o.append("\nHeard but not in the lyric sheet (extra repeats / ad-libs):\n")
for e in T["heard_not_in_lyrics"]: o.append("- %s-%s: \"%s\"" % (ts(e["start"]), ts(e["end"]), e["text"]))
src = {}
for x in T["words"]: src[x["source"]] = src.get(x["source"], 0) + 1
o.append("\nWord sources: %s (full-file large-v3 pass; 10-30 s from a clipped second pass because the full pass skipped the first verse; a few words from a pass on the separated vocal stem, accepted only when they equal a lyric token). Whisper word `end` times are loose, so line `end` = last matched word start + min(raw duration, 0.09 s per character + 0.2 s).\n" % src)
o.append("## Singers (hint only: pyin f0 on a separated vocal stem; not ground truth)\n")
c = T["singer_calibration"]
o.append("- Threshold %.0f Hz = geometric mean of the Verse 1 median (tag male, %.0f Hz) and the Pre-Chorus 1 + female-bridge median (tag female, %.0f Hz): calibrated on the tags themselves, so tag agreement below is partly circular. 230-380 Hz is marked low confidence (voices overlap; sustained instrument notes leak into the stem)." % (c["threshold_hz_geomean"], c["male_ref_median_hz"], c["female_ref_median_hz"]))
hi = [L for L in Ls if L["singer_hint_confidence"] == "high" and L["singer_tag"] in ("male", "female")]
agree = [L for L in hi if L["singer_hint"] == L["singer_tag"]]
o.append("- Tag vs hint on high-confidence male/female-tagged lines: %d/%d agree. Disagreements: %s." % (len(agree), len(hi), "; ".join("%s \"%s\" tag %s hint %s (%s Hz)" % (L["section"], L["text"][:24], L["singer_tag"], L["singer_hint"], L["f0_median_hz"]) for L in hi if L["singer_hint"] != L["singer_tag"]) or "none"))
b = T["bridge_voice_check"]
if b:
    o.append("- **Bridge halves**: male half median f0 %.0f Hz (%d voiced frames, %.0f%% below threshold) vs female half %.0f Hz (%d frames, %.0f%% below threshold): gap %.1f semitones, Mann-Whitney p = %.1e. The two halves are sung in clearly different pitch ranges, consistent with two different voices; the male half sits high (~E-flat 4) so it is a high tenor, and the last male line has no usable pitch." % (
        b["male_half_median_hz"], b["n_male"], 100 * b["male_half_frac_below_threshold"], b["female_half_median_hz"], b["n_female"], 100 * b["female_half_frac_below_threshold"], b["semitone_gap"], b["mannwhitney_p"]))
o.append("- Verse 2 is tagged female but two of its four lines sit at 261-277 Hz (low-confidence 'male' hint): either a low female register or the male voice; this cannot be settled from f0 alone. Pre-Chorus 2 (tag male) sits at 261-271 Hz, same caveat.")
o.append("")
o.append("## Dynamics (RMS dB per bar, mean of bars)\n")
def wmean(names):
    xs = [s for s in S if s["name"] in names]; n = sum(s["n_bars"] for s in xs)
    return sum(s["mean_db"] * s["n_bars"] for s in xs) / n
verse = wmean(("Verse 1", "Verse 2")); chor = wmean(("Chorus 1", "Chorus 2", "Final Chorus (full, duet)")); chor12 = wmean(("Chorus 1", "Chorus 2"))
bm = next(s for s in S if s["name"] == "Bridge (male)"); bf = next(s for s in S if s["name"] == "Bridge (female)")
o.append("- Verses %.1f dB (V1 %.1f, V2 %.1f), choruses %.1f dB (C1 %.1f, C2 %.1f, final full %.1f): chorus is only **+%.1f dB** above verse (+%.1f for C1/C2 alone). Pre-choruses %.1f / %.1f dB." % (
    verse, next(s["mean_db"] for s in S if s["name"] == "Verse 1"), next(s["mean_db"] for s in S if s["name"] == "Verse 2"), chor, next(s["mean_db"] for s in S if s["name"] == "Chorus 1"), next(s["mean_db"] for s in S if s["name"] == "Chorus 2"),
    next(s["mean_db"] for s in S if s["name"] == "Final Chorus (full, duet)"), chor - verse, chor12 - verse, next(s["mean_db"] for s in S if s["name"] == "Pre-Chorus 1"), next(s["mean_db"] for s in S if s["name"] == "Pre-Chorus 2")))
o.append("- Bridge: the **male half is loud** (%.1f dB, same as the choruses) and the **female half is the dip** (%.1f dB mean, quietest bar %.1f dB): dip depth %.1f dB below the choruses, %.1f dB below the verses. The brief's order (male = near silent, female = building back) is reversed in the render; the dip is %d bars (%s-%s), then the instrumental break jumps +%.1f dB (to %.1f dB)." % (
    bm["mean_db"], bf["mean_db"], bf["min_bar_db"], chor - bf["mean_db"], verse - bf["mean_db"], bf["n_bars"], ts(bf["start"]), ts(bf["end"]), next(s["mean_db"] for s in S if s["name"] == "Instrumental Break") - bf["mean_db"], next(s["mean_db"] for s in S if s["name"] == "Instrumental Break")))
fs = next(s for s in S if s["name"] == "Final Chorus (stripped, female)"); fb = next(s for s in S if s["name"] == "Final Chorus (full, duet)")
o.append("- 'Stripped quiet' final chorus half is %.1f dB (vs %.1f for the full one): +%.1f dB step only, not a real drop." % (fs["mean_db"], fb["mean_db"], fb["mean_db"] - fs["mean_db"]))
loud = max(S, key=lambda s: s["mean_db"])
o.append("- Loudest section: %s (%.1f dB, %s-%s), after the final chorus and not part of the lyric sheet. Fade: last three bars %.1f dB." % (loud["name"], loud["mean_db"], ts(loud["start"]), ts(loud["end"]), S[-1]["mean_db"]))
va = T["vocal_activity"]
o.append("- Vocal-stem activity (> -45 dB) spans: " + "; ".join("%s-%s (%d words)" % (ts(v["start"]), ts(v["end"]), v["words_heard"]) for v in va) + ". Spans with 0 words are non-lexical vocals (intro oh-oh at ~3-5 s, a low-level vocal layer under the loud coda 213-228 s, the final whisper).")
o.append("")
o.append("## Key\n")
o.append("Krumhansl-Schmuckler on harmonic chroma per section (r = correlation of the best key; F minor / F major / C major are close, mode is ambiguous because the harmony mixes them):\n")
o.append("| section | best key (r) | second (r) |"); o.append("|---|---|---|")
for k in T["key_per_section"]: o.append("| %s | %s (%.2f) | %s (%.2f) |" % (k["section"], k["best"], k["r"], k["second"], k["r2"]))
sh = T["key_shift_between_choruses"]
acc = T["accompaniment_shift_vs_chorus2_2bar"]
fin = [a for a in acc if 172 <= a["start"] <= 206]
o.append("\n**Key change in the final chorus: not detected.** Chroma of Chorus 2 vs Final Chorus (full): best shift %d semitones (r %.2f, same at 0). On the accompaniment stem, every 2-bar window from %s to %s has best shift 0 vs Chorus 2 except %d window(s) with a +1 (r %s): %s. Sung 'Ay dolar' phrase pitch (median MIDI): %s; the only high one (%s) is +1.9 semitones over Chorus 1 and is a single repeat while the band does not move. Suno did not modulate."  % (
    sh["Chorus2_vs_FinalFull"]["best_shift_semitones"], sh["Chorus2_vs_FinalFull"]["r_at_best"], ts(fin[0]["start"]), ts(fin[-1]["start"]), sum(a["best_shift_semitones"] != 0 for a in fin), ", ".join(str(a["r_best"]) for a in fin if a["best_shift_semitones"] != 0), ", ".join("%s bar %d" % (ts(a["start"]), a["bar"]) for a in fin if a["best_shift_semitones"] != 0),
    ", ".join("%s: %.2f" % (ts(p["t"]), p["midi"]) for p in T["ay_dolar_phrase_pitch"]), ", ".join(ts(p["t"]) for p in T["ay_dolar_phrase_pitch"] if p["midi"] > 68.5)))
o.append("")
o.append("## Hit candidates (`hits[]`, %d strongest onsets)\n" % len(T["hits"]))
sn = [h for h in T["hits"] if h["beat_idx"] is not None]
o.append("%d of %d snap to a beat within 1 frame (`t_snapped`, `beat_idx`); the rest keep their raw time. Top 20 by strength:\n" % (len(sn), len(T["hits"])))
o.append("| t | strength | band | beat | dt ms |"); o.append("|---|---|---|---|---|")
for h in sorted(T["hits"], key=lambda h: -h["strength"])[:20]: o.append("| %s | %.2f | %s | %s | %+.0f |" % (ts(h["t"]), h["strength"], h["dominant_band"], h["beat_idx"] if h["beat_idx"] is not None else "-", h["dt_ms"]))
o.append("")
o.append("## Not measured / caveats\n")
o.append("- Whisper word times for the first word after a rest are late or early by up to ~1 s (no forced alignment); line starts are good to ~0.3 s, not to the frame. Use the bar grid and `hits[]` for frame-exact sync.")
o.append("- Chorus 2 'Bilmiyorum' is unanchored: it was heard on the vocal-stem pass at 2:00.4 but in the mix pass the words around it carry inconsistent times, so the monotone alignment could not place it. The intro '(oh, oh)' is only visible as vocal energy, not as words.")
o.append("- Final-chorus 'merhaba de' was heard as 'ne var' (2 of 4 words matched). The final spoken 'Merhaba' (3:55.5) was heard as a word but the lyric sheet has one Merhaba line, which the alignment placed at 3:31.06; the 3:55.5 word is listed in words[] with line = null.")
o.append("- Singer hints are pitch-range only; no speaker identification. Time signature was assumed 4/4 and held on every bar.")
o.append("- Section names after 'Outro' (part 2-4) are my labels for measured energy blocks, not from the lyric sheet. Key estimates are template-based and ambiguous between F minor, F major and C major.")
o.append("\nRegenerate: `beatgrid.py` -> `downbeats.py 6` -> whisper (`whisper_words.py`, three passes: full, `10,34` clip, vocal stem via demucs) -> `build_timing.py` -> `verify_grid.py` -> `make_summary.py` (all via `uv run --with ...`, see file headers).")
open(R + "timing-summary.md", "w", encoding="utf-8").write("\n".join(o) + "\n")
print("\n".join(o)[:200]); print("written", len(o), "blocks")
